    @Test
    public void testSampleDataTest(){
        DataManager dataManager = new DataManager(
                "./data/dataset.csv", "./data/labels.csv"
        );
        final int EXPECTED_SIZE = 640;

        assertEquals(EXPECTED_SIZE, dataManager.getTrainingMatrixPair()[0].rows());

        int counter = 0;
        for (int i = 0; i < EXPECTED_SIZE; i++){
            double _ = dataManager.getTrainingMatrixPair()[0].get(i,0); //No exception thrown, means data
            counter++;
        }
        assertEquals(EXPECTED_SIZE, counter);
    }

    @Test
    public void testSampleLabelsTest(){
        DataManager dataManager = new DataManager(
                "./data/dataset.csv", "./data/labels.csv"
        );
        final int EXPECTED_SIZE = 640;

        assertEquals(EXPECTED_SIZE, dataManager.getTrainingMatrixPair()[1].rows());

        int counter = 0;
        for (int i = 0; i < EXPECTED_SIZE; i++){
            double _ = dataManager.getTrainingMatrixPair()[1].get(i,0); //No exception thrown, means data
            counter++;
        }

        assertEquals(EXPECTED_SIZE, counter);
    }
